"use client";

import type { ReactNode } from "react";
import { AbsoluteFill } from "remotion";
import {
  AUDIT_COLORS,
  AuditClock,
  DEMO,
  DemoDashboard,
  easeInOut,
  FONT,
  IssueMarks,
  MeasureMarks,
  ScanBand,
  SplitAt,
  useAuditFrame,
  VersionChip,
} from "@/lib/remocn/audit-core";
import { useSceneConfig } from "@/lib/remocn/frame-rate";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import { type ScanFixElementId, scanFixTimeline } from "./timeline";

export type ScanFixProps = {
  /** Frame before the fix, 1280x720. Defaults to the demo dashboard with red redlines. */
  before?: ReactNode;
  /** Frame after the fix, same size. Defaults to the fixed dashboard with blue redlines. */
  after?: ReactNode;
  /** Name next to the version chip. Empty hides the chip. */
  brand?: string;
  /** Version chip text before and after the band passes it. */
  versions?: [string, string];
  scanColor?: string;
  beforeColor?: string;
  afterColor?: string;
  background?: string;
  speed?: number;
  /**
   * Moves, trims or stretches the scan, by the ids in `./timeline`. Frames
   * on the scene timeline, after `speed`.
   */
  timing?: Timing<ScanFixElementId>;
};

export const scanFixDefaults = {
  brand: "Synergy",
  versions: ["v1.0", "v2.0"] as [string, string],
  scanColor: AUDIT_COLORS.scan,
  beforeColor: AUDIT_COLORS.audit,
  afterColor: AUDIT_COLORS.fix,
  background: AUDIT_COLORS.stage,
  speed: 1,
};

export const scanFixLength = 100;

export function ScanFix(props: ScanFixProps) {
  const { speed = 1 } = props;
  return (
    <AuditClock speed={speed}>
      <Scene {...props} />
    </AuditClock>
  );
}

function DemoBefore({ color }: { color: string }) {
  return (
    <>
      <DemoDashboard v={1} />
      <MeasureMarks
        measures={DEMO.before.measures}
        radii={DEMO.before.radii}
        color={color}
        start={-200}
      />
      <IssueMarks issues={DEMO.before.issues} color={color} start={-200} />
    </>
  );
}

function DemoAfter({ color }: { color: string }) {
  return (
    <>
      <DemoDashboard v={2} />
      <MeasureMarks
        measures={DEMO.after.measures}
        radii={DEMO.after.radii}
        color={color}
        start={-200}
      />
    </>
  );
}

function Scene(props: ScanFixProps) {
  const {
    before,
    after,
    brand = scanFixDefaults.brand,
    versions = scanFixDefaults.versions,
    scanColor = scanFixDefaults.scanColor,
    beforeColor = scanFixDefaults.beforeColor,
    afterColor = scanFixDefaults.afterColor,
    background = scanFixDefaults.background,
    speed = 1,
    timing,
  } = props;
  const frame = useAuditFrame();
  const { durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    scanFixTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const scan = tl.get("scan");
  const y = easeInOut(frame, [scan.start, scan.end], [-20, 760]);
  const band = easeInOut(
    frame,
    [
      scan.start + scan.beat("bandIn"),
      scan.start + scan.beat("bandOn"),
      scan.start + scan.beat("bandOff"),
      scan.start + scan.beat("bandGone"),
    ],
    [0, 1, 1, 0],
  );
  return (
    <AbsoluteFill style={{ background, fontFamily: FONT }}>
      <SplitAt
        y={y}
        bottom={before ?? <DemoBefore color={beforeColor} />}
        top={after ?? <DemoAfter color={afterColor} />}
      />
      {brand && (
        <VersionChip
          brand={brand}
          versions={versions}
          fixed={y > 36}
          colors={[beforeColor, afterColor]}
        />
      )}
      <ScanBand y={y} color={scanColor} opacity={band} />
    </AbsoluteFill>
  );
}

import { defineTimeline } from "@/lib/remocn/timeline";

// The scan band sweeping down the frame, turning the "before" build into the
// "after" one as it passes. Frames on the 30 fps scene timeline, after
// `speed`. The id is public: a saved `timing` prop refers to it.

export type ScanFixElementId = "scan";

const SCAN_START = 18;
const SCAN_LENGTH = 80;

// `scan` moves the band from the top edge to the bottom over its length. The
// band fades in from `bandIn` to `bandOn` and out from `bandOff` to
// `bandGone`, counted from the scan's start.
export const scanFixTimeline = defineTimeline<ScanFixElementId, object>(() => [
  {
    id: "scan",
    lane: "Scan",
    label: "Scan",
    start: SCAN_START,
    length: SCAN_LENGTH,
    beats: {
      bandIn: -4,
      bandOn: 2,
      bandOff: SCAN_LENGTH - 6,
      bandGone: SCAN_LENGTH + 2,
    },
  },
]);
